import string
import random

from ute_ue.voice_call import DefaultBaseVoiceCall
from ta_ue_plugin_ultracaller.exceptions import UltraCallerTestPhaseException, UltraCallerTestReturnsError


class UcVoiceCall(DefaultBaseVoiceCall):
    """
    Ultracaller implementation of voice call.
    Supported parameters duration and number to be dialed.
    """
    TIME_FORMAT = "%a, %d %b %Y %H:%M:%S"

    def __init__(self, name, ue_name, definition, imei, uc_connection, logger_name='ute_ue'):
        """
        Basic initialization.

        :param name: name to assign for new voice call
        :param ue_name: name of UE where we start voice call at
        :param definition: description of voice call, instance of VoiceCallDefinition
        :param imei: IMEI of UE where we start voice call at
        :param uc_connection: UltraCaller connection - instance of UcConnection
        :param logger_name: where to put logs from this voice call

        """
        super(UcVoiceCall, self).__init__(name, ue_name, definition, logger_name)
        self._imei = imei
        self._uc_connection = uc_connection
        self._test_id = None
        self._test_name = None
        self._start_time = None
        self._stop_time = None
        self._running = False

    def _start_call_on_ue(self, to):
        self.logger.info('Starting new voice call: "{}" '.format(self.name))

        # Create new test
        self._test_name = '{}_{}'.format(self.name, ''.join(
            random.choice(string.ascii_uppercase + string.digits) for _ in range(5)))
        params = {"phoneNumber": to, "duration": 863913600, "sipCall": False}
        self._uc_connection.new_test(name=self._test_name, test_type='Voice call', test_params=params)
        self.logger.debug('Created new test {} type Voice call with params {}'.format(self._test_name, params))

        # Start created test
        response = self._uc_connection.start_test(self._imei, self._test_name)
        self._test_id = response['data'][0]['testId']

        if self._uc_connection.wait_until_test_phase(test_id=self._test_id, phase='running'):
            self._running = True
        else:
            self.logger.debug('Voice call FAILED to start within time limit')
            raise UltraCallerTestPhaseException('running')

    def stop(self):
        """
        Stop voice call
        :return:
        """
        self.stop_voice_call()

    def _end_call_on_ue(self):
        self.logger.info('Stopping Voice call "{}" '.format(self.name))

        try:
            response = self._uc_connection.test_status(test_id=self._test_id)
            if response['data']['phase'] == 'running':
                self._uc_connection.stop_test(imei=self._imei, test_id=self._test_id)
                if self._uc_connection.wait_until_test_phase(test_id=self._test_id, phase='completed'):
                    self._running = False
                else:
                    self.logger.debug('Voice call FAILED to stop within time limit')
                    raise UltraCallerTestPhaseException('completed')

            results = self._uc_connection.get_test_result(test_id=self._test_id)
            self._check_result(results)
        finally:
            self._uc_connection.delete_test(test_name=self._test_name)

    def _check_result(self, test_result):
        for item in test_result['data']:
            if item['phase'] == 'completed' and item['status'] == 'success':
                self.logger.info('Voice call {} successful'.format(self.name))
                break
        else:
            self.logger.debug('Voice call FAILED to complete')
            raise UltraCallerTestReturnsError('Voice call failed')
